import{_ as r,I as a,c as s,o as i,a3 as t,b as l,w as o,a as c,J as d,a4 as u}from"./chunks/framework.MI-M1z4O.js";const S=JSON.parse('{"title":"Concurrent Session Arbitration & White-Screen False Positive Prevention Guide","description":"Runtime guide for arbitrating session conflicts across multiple crawlers sharing an account and preventing white-screen false positives caused by SPA rendering delays","frontmatter":{"title":"Concurrent Session Arbitration & White-Screen False Positive Prevention Guide","shortTitle":"Session Arbitration & Stability","category":"Runtime Stability & Security","sort":12,"description":"Runtime guide for arbitrating session conflicts across multiple crawlers sharing an account and preventing white-screen false positives caused by SPA rendering delays","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/synccrawl/session-arbitration"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synccrawl/session-arbitration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synccrawl/session-arbitration"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synccrawl/session-arbitration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synccrawl/session-arbitration"}]]},"headers":[],"relativePath":"en/synccrawl/session-arbitration.md","filePath":"en/synccrawl/session-arbitration.md","lastUpdated":1795293539000}'),h={name:"en/synccrawl/session-arbitration.md"};function m(p,e,g,b,k,f){const n=a("Mermaid");return i(),s("div",null,[e[1]||(e[1]=t('<h1 id="concurrent-session-arbitration-white-screen-false-positive-prevention-guide" tabindex="-1">Concurrent Session Arbitration &amp; White-Screen False Positive Prevention Guide <a class="header-anchor" href="#concurrent-session-arbitration-white-screen-false-positive-prevention-guide" aria-label="Permalink to “Concurrent Session Arbitration &amp; White-Screen False Positive Prevention Guide”">​</a></h1><h2 id="_1-overview-runtime-failure-modes" tabindex="-1">1. Overview &amp; Runtime Failure Modes <a class="header-anchor" href="#_1-overview-runtime-failure-modes" aria-label="Permalink to “1. Overview &amp; Runtime Failure Modes”">​</a></h2><p>Two of the most common failure modes encountered by web automation crawlers in production enterprise environments stem from <strong>concurrent multi-login blocking policies</strong> on target sites and <strong>asynchronous rendering delays in SPAs (Single Page Applications)</strong>:</p><ol><li><strong>Concurrent Login Session Kick</strong>: <ul><li>When multiple crawler workers attempt to log in simultaneously using the same service account, existing sessions are forcibly terminated or the account is temporarily locked out due to anomalous access detection.</li></ul></li><li><strong>White-Screen False Positives</strong>: <ul><li>On React or Vue-based SPA sites, JavaScript chunk downloads or API latency can leave the viewport temporarily blank. Crawlers may misinterpret this transient state as a page load failure and trigger unnecessary retries.</li></ul></li></ol><p><code>SyncCrawl</code> stabilizes these runtime exceptions using a <strong>centralized session arbitration queue</strong> and a <strong>DOM mutation-based rendering verification engine</strong>.</p>',5)),(i(),l(u,null,{default:o(()=>[d(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20MultiWorkers%20%5B%22Multiple%20Crawler%20Workers%20(Worker%201%20~%20N)%22%5D%0A%20%20%20%20%20%20%20%20W1%5B%22Worker%201%20(Crawl%20Request)%22%5D%0A%20%20%20%20%20%20%20%20W2%5B%22Worker%202%20(Crawl%20Request)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Arbitration%20%5B%22Session%20Arbitrator%22%5D%0A%20%20%20%20%20%20%20%20Queue%5B%22Redis-Based%20Per-Account%20Session%20Queue%22%5D%0A%20%20%20%20%20%20%20%20CookieStore%5B(%22Encrypted%20Session%20Cookie%20Store%20(Redis)%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20W1%20%26%20W2%20--%3E%20Queue%0A%20%20%20%20Queue%20--%3E%20Check%7B%22Valid%20Session%20Cookie%20Exists%3F%22%7D%0A%20%20%20%20Check%20--%20%22Valid%20Cookie%20Exists%22%20--%3E%20Reuse%5B%22Skip%20Login%3A%20Inject%20Existing%20Session%20Cookie%22%5D%0A%20%20%20%20Check%20--%20%22Cookie%20Expired%20%2F%20Absent%22%20--%3E%20SingleLogin%5B%22Single%20Worker%20Performs%20Login%20(Distributed%20Lock)%22%5D%0A%20%20%20%20SingleLogin%20--%3E%20UpdateStore%5B%22Store%20New%20Cookie%20%26%20Share%20with%20Waiting%20Workers%22%5D%0A%0A%20%20%20%20Reuse%20%26%20UpdateStore%20--%3E%20RenderCheck%7B%22Rendering%20Status%20Check%20(DOM%20Mutation%20%2B%20NetworkIdle)%22%7D%0A%20%20%20%20RenderCheck%20--%20%22White%20Screen%20(Async%20Loading)%22%20--%3E%20Wait%5B%22Exponential%20Backoff%20Wait%20(Max%2010s)%22%5D%0A%20%20%20%20Wait%20--%3E%20RenderCheck%0A%20%20%20%20RenderCheck%20--%20%22Semantic%20Components%20Mounted%22%20--%3E%20Extract%5B%22Proceed%20with%20Normal%20Data%20Extraction%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="_2-concurrent-multi-login-session-arbitration" tabindex="-1">2. Concurrent Multi-Login Session Arbitration <a class="header-anchor" href="#_2-concurrent-multi-login-session-arbitration" aria-label="Permalink to “2. Concurrent Multi-Login Session Arbitration”">​</a></h2><p>When multiple crawler workers execute jobs against the same target site simultaneously, a centralized arbitration mechanism prevents redundant login attempts.</p><h3 id="_1-session-cookie-store-reuse" tabindex="-1">1) Session Cookie Store &amp; Reuse <a class="header-anchor" href="#_1-session-cookie-store-reuse" aria-label="Permalink to “1) Session Cookie Store &amp; Reuse”">​</a></h3><ul><li>Before initiating a login sequence, each crawler worker checks the Redis session store to see if a valid session (Cookies &amp; LocalStorage) already exists for that account.</li><li>If a valid session is found, the worker injects the cookies directly into the browser context and navigates straight to the target page without hitting the login screen.</li></ul><h3 id="_2-atomic-single-flight-login" tabindex="-1">2) Atomic Single-Flight Login <a class="header-anchor" href="#_2-atomic-single-flight-login" aria-label="Permalink to “2) Atomic Single-Flight Login”">​</a></h3><ul><li>When a session expires and re-authentication is required, only the single worker that acquires the distributed lock <code>account:lock:{siteId}:{username}</code> submits the login form and authenticates.</li><li>All other workers wait in the session queue. Once the lead worker completes authentication and updates the store with fresh cookies, the waiting workers receive those cookies and resume simultaneously.</li><li>This prevents concurrent duplicate logins on the target site and avoids triggering account protection lockouts.</li></ul><hr><h2 id="_3-white-screen-false-positive-prevention-algorithm" tabindex="-1">3. White-Screen False Positive Prevention Algorithm <a class="header-anchor" href="#_3-white-screen-false-positive-prevention-algorithm" aria-label="Permalink to “3. White-Screen False Positive Prevention Algorithm”">​</a></h2><p>Relying solely on <code>networkidle</code> or <code>DOMContentLoaded</code> events can cause crawlers to capture a blank white screen when network requests have finished but client-side virtual DOM rendering is still in progress.</p><p><code>SyncCrawl</code> evaluates page readiness by combining three composite signals:</p><ol><li><strong>DOM Mutation Observer Integration</strong>: <ul><li>Verifies quiescence under <code>document.body</code>—confirming that no additional child node insertions or text mutations occur for 500ms.</li></ul></li><li><strong>Text Density &amp; Visible Node Evaluation</strong>: <ul><li>Checks that the total character count of user-visible text nodes and block elements (<code>&lt;p&gt;</code>, <code>&lt;div&gt;</code>, <code>&lt;tr&gt;</code>, etc.) within the rendered viewport meets a minimum threshold (e.g., at least 50 characters of text).</li></ul></li><li><strong>Loading Spinner Disappearance Detection</strong>: <ul><li>Ensures common loading indicator classes and attributes (e.g., <code>.spinner</code>, <code>.loading</code>, <code>[role=&quot;progressbar&quot;]</code>) have completely disappeared from the DOM before transitioning to data extraction.</li></ul></li></ol><hr><h2 id="_4-temporary-file-download-isolation-auto-cleanup" tabindex="-1">4. Temporary File Download Isolation &amp; Auto-Cleanup <a class="header-anchor" href="#_4-temporary-file-download-isolation-auto-cleanup" aria-label="Permalink to “4. Temporary File Download Isolation &amp; Auto-Cleanup”">​</a></h2><ul><li>If a crawler terminates while downloading large attachments or PDF disclosure documents, incomplete downloads can cause disk exhaustion or corrupted artifacts.</li><li>Each worker process isolates downloads in a UUID-scoped temporary directory (<code>/tmp/crawl_session_{uuid}</code>). Only files that pass SHA-256 hash verification upon completion are promoted to permanent object storage (MinIO), after which the temporary directory is immediately purged (<code>clean-up</code>).</li></ul>',15))])}const v=r(h,[["render",m]]);export{S as __pageData,v as default};
